# Own-wording backgrounds of Grim Hollow Campaign Guide (2014 rules). Record shape follows tgh14p_bg.py.
# Each background is a variant of a parent group. Ability and feat are assigned thematically, the book lists none.
OPTS = ["Actor", "Alert", "Crafter", "Healer", "Inspiring Leader", "Linguist", "Lucky", "Magic Initiate (Cleric)", "Magic Initiate (Wizard)", "Musician", "Savage Attacker", "Skilled", "Tavern Brawler", "Tough"]
