RK = " Four ranks are listed in the book: %s. Each rank has holdings and a way to advance."
def _bg(ab, sk, pick, tool, eq, gp, feat, feature, text, ranks, lang=1, tp=None, lgf=None):
    r = {"ab": ab, "sk": sk, "tool": tool, "eq": eq, "gp": gp, "lgn": lang, "feat": feat,
         "bf": [[feature, text], [feature.split(" ")[0] + " Ranks" if False else "Ranks", RK.strip().replace("%s", ", ".join(ranks)).replace(" Four ranks are", "Four ranks are")]]}
    if pick: r["skPick"] = {"n": 1, "from": pick}
    if tp: r["toolPick"] = tp
    if lgf: r["lgf"] = lgf; r["langs"] = lgf
    return r
def _rk(ranks): return "Four ranks are listed in the book: %s. Each rank has holdings and a way to advance." % ", ".join(ranks)
def B(ab, sk, pick, tool, eq, gp, feat, feature, text, ranks, lang=1, tp=None, lgf=None, extra=""):
    r = {"ab": ab, "sk": sk, "tool": tool, "eq": eq, "gp": gp, "lgn": lang, "feat": feat, "bf": [[feature, text], ["Ranks", _rk(ranks)]]}
    if extra: r["bf"].insert(0, ["Language", extra])
    if pick: r["skPick"] = {"n": 1, "from": pick}
    if tp: r["toolPick"] = tp
    if lgf: r["lgf"] = lgf; r["langs"] = lgf
    return r
